function tlockOpen() {
  if ($('#tlock')) return; const d = document.createElement('div'); d.id = 'tlock'; d.className = 'modal';
  d.innerHTML = `<div class="frame" style="--c:var(--cyan)"><div class="lbl">TEACHER ACCESS</div><p>교사 콘솔로 들어가려면 교사 번호를 입력하세요.</p>
