    <div class="row"><button class="btn" data-tlock-go>열기</button><button class="btn ghost" data-tlock-x>닫기</button></div><div id="tlockMsg"></div></div>`;
  document.body.appendChild(d); setTimeout(() => { const i = $('#tlockPin'); if (i) i.focus(); }, 50);
}
function tlockClick(e) {
  if (e.target.closest('[data-tlock]')) { tlockOpen(); return true; }
  if (e.target.closest('[data-tlock-x]')) { const m = $('#tlock'); if (m) m.remove(); return true; }
  if (e.target.closest('[data-tlock-go]')) {
    if (($('#tlockPin') || {}).value === TEACHER_PIN) { try { sessionStorage.setItem('chronos:pin','ok'); } catch (err) {} location.hash = 'teacher'; }
    else { $('#tlockMsg').innerHTML = '<div class="deny">ACCESS DENIED</div>'; Sound.no(); }
    return true;
  }
  return false;
}
